BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats16-q01', '時系列解析',
   '「クラス40人のテストの点数」を並べたデータと、「ある店の1月から12月までの毎月の来客数」を並べたデータには、決定的な違いがある。どれ？',
   NULL::text,
   '["テストの点数は並べる順番を入れ替えても意味が変わらないが、来客数は月の順番を入れ替えると意味そのものが変わってしまう", "テストの点数は40人ぶんの40個しかないが、来客数は1月から12月までの12個で、扱う数値の個数がそもそも違っている", "テストの点数は0点から100点までの範囲に収まるが、来客数は0人から何人にでもなりうるという、範囲の広さの違いがある", "テストの点数は生徒一人ひとりの記録だが、来客数はその店という1つの対象だけをまとめて記録したものになっている"]',
   0, '[0]', 'single',
   '{"asked": "何をもって「時系列データ」と呼ぶのか、その決め手になる違い。", "point": "順番(時間の前後)を入れ替えたら意味が変わってしまうデータが時系列データ。", "kid": "テストの点数は、太郎さんの点数の後に花子さんの点数が来ようが、順番を変えても『40人の点数の集まり』という意味は変わらない。でも来客数は、1月・2月・3月…という順番のまま見て初めて『増えている』『減っている』という流れが分かる。順番を崩したら、その流れは分からなくなる。", "eg": "写真アルバムに例えると分かりやすい。ページの順番を入れ替えても、1枚1枚の写真そのものは同じ。でも『赤ちゃんの頃から今まで成長していく様子』という意味は、正しい順番に並んでいて初めて伝わる。時系列データはこの、順番込みで意味を持つデータ。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">順番に意味が無いデータ／ある(時系列)データ</text>\n<text x=\"85\" y=\"32\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">クラス40人のテストの点数</text>\n<rect x=\"25\" y=\"40\" width=\"120\" height=\"70\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<circle cx=\"50\" cy=\"62\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"95\" cy=\"50\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"70\" cy=\"90\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"120\" cy=\"75\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"55\" cy=\"95\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"110\" cy=\"55\" r=\"4\" fill=\"#60a5fa\"/>\n<text x=\"85\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">並べ替えても意味は変わらない</text>\n<text x=\"255\" y=\"32\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">来客数(1月→12月)</text>\n<rect x=\"195\" y=\"40\" width=\"120\" height=\"70\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<polyline points=\"205,90 225,70 245,78 265,55 285,62 305,45\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<circle cx=\"205\" cy=\"90\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"225\" cy=\"70\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"245\" cy=\"78\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"265\" cy=\"55\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"285\" cy=\"62\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"305\" cy=\"45\" r=\"3\" fill=\"#3b82f6\"/>\n<text x=\"255\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">順番を変えると流れが分からなくなる</text>\n<text x=\"170\" y=\"140\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">順番そのものに意味があるのが時系列データ</text>\n</svg>", "terms": [["時系列データ", "時間の順に並んでいて、並び順そのものに意味があるデータ"], ["観測順序", "データが記録された時間の前後関係"]], "think": "なぜ順番を入れ替えると意味が変わるのかがカギ。来客数は、前の月から今の月にかけて増えたのか減ったのか、という『変化の向き』を表している。順番を入れ替えると、どちらからどちらへ変化したのかが分からなくなり、増減の流れという情報そのものが消えてしまう。一方テストの点数は、40人分の点数がただ集まっているだけで、誰の点数が先に書いてあるかは点数の意味に関係しない。だから、順番に意味があるかどうかが、時系列データとそうでないデータを分ける決め手になる。", "vs": "『データの個数が多い・少ない』『数値の範囲が広い・狭い』といった見た目の違いに気を取られない。時系列データかどうかを決めるのは、あくまで並び順に意味があるかどうかという1点だけ。", "why_asked": "この後に学ぶトレンド・季節変動・自己相関・定常性は、すべて『順番に意味がある』ことを前提にした考え方。この前提を先に押さえておかないと、なぜわざわざ順番を気にする特別な分析(時系列解析)が必要なのかが分からなくなる。", "usecase": "株価・気温・毎日の体重・毎月の売上のように、日付や時刻ごとに1つの数値が記録されているデータは、すべて時系列データにあたる。", "opt": ["正解。来客数は月の順番のまま見て初めて『増えた・減った』という流れが分かる。順番を崩すとその流れの情報が消えてしまうので、順番に意味があるかどうかが決定的な違いになる。", "データの個数の違いはたまたま今回の例がそうなっているだけで、時系列データかどうかを決める性質ではない。テストの点数を12人分にしても、順番に意味が無いことは変わらない。", "数値の取りうる範囲の違いも、たまたま今回の例の話。範囲が広くても狭くても、順番に意味があるかどうかとは関係ない。", "個人ごとの記録か、1つの対象だけの記録かという違いも、時系列データかどうかを決める性質ではない。1つの対象を1回だけ記録したデータも、複数人をまとめて記録したデータも、順番に意味があれば時系列データになりうる。"]}'),

  ('stats16-q02', '時系列解析',
   'ある町のアイス屋の月ごとの売上を5年間記録すると、①年々売上が右肩上がりに伸びている、②毎年7〜8月にいつも売上がぐんと伸び、1〜2月にいつも落ち込む、という2つの動きが同時に見える。この①と②をそれぞれ何と呼ぶ？',
   NULL::text,
   '["①のような長期的な右肩上がり・右肩下がりを「トレンド」、②のような毎年同じ時期に繰り返す動きを「季節変動」と呼ぶ", "①のような長期的な右肩上がり・右肩下がりを「季節変動」、②のような毎年同じ時期に繰り返す動きを「トレンド」と呼ぶ", "①も②も合わせて「トレンド」と呼び、2つの動きを区別する言葉は特に無い", "①も②も合わせて「季節変動」と呼び、2つの動きを区別する言葉は特に無い"]',
   0, '[0]', 'single',
   '{"asked": "時系列データに同時に現れる、2種類の動きの名前。", "point": "長期でならしたときの右肩上がり・下がりが『トレンド』、毎年同じ時期に繰り返す山谷が『季節変動』。", "kid": "トレンドは『何年も先まで見たときに、全体としてどっちに向かっているか』という大きな流れ。季節変動は『1年という決まった長さの中で、毎回同じ時期に繰り返すでこぼこ』。この2つは別の種類の動きなので、別の名前で呼び分ける。", "eg": "潮の満ち引きに例えると分かりやすい。1日のうちに満潮・干潮が繰り返すのは季節変動にあたる短い周期の動き。一方、何十年もかけて海面の高さそのものがじわじわ上がっているとしたら、それがトレンドにあたる長期の流れ。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">アイス屋の月次売上(5年分)</text>\n<line x1=\"30\" y1=\"120\" x2=\"315\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<polyline points=\"30,100 55,60 80,95 105,88 130,45 155,80 180,72 205,32 230,65 255,58 280,20 305,50\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/>\n<path d=\"M30,92 L305,52\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\n<circle cx=\"130\" cy=\"45\" r=\"3\" fill=\"#6ab08d\"/>\n<circle cx=\"280\" cy=\"20\" r=\"3\" fill=\"#6ab08d\"/>\n<text x=\"130\" y=\"38\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">夏に山</text>\n<text x=\"280\" y=\"14\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">夏に山</text>\n<text x=\"60\" y=\"136\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">実際の売上(でこぼこ)</text>\n<text x=\"255\" y=\"136\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">トレンド(右肩上がり)</text>\n</svg>", "terms": [["トレンド", "長期的にみたときの、右肩上がり・右肩下がりといった大きな流れ"], ["季節変動", "1年など決まった長さの中で、毎回同じ時期に繰り返される周期的な増減"]], "think": "なぜこの2つをわざわざ分けて考えるのかがカギ。もし『今年の夏は去年の夏よりどれだけ本当に伸びたか』を知りたいとき、トレンドと季節変動を一緒くたにしたままだと、単に『夏だから毎年増える』分と『商売そのものが年々伸びている』分の区別がつかない。2つの動きを別の名前で呼び分けて、それぞれ取り出せるようにしておくことで、はじめて『本当の意味での伸び』を取り出せるようになる。", "vs": "トレンドは何年もかけたゆっくりした流れ、季節変動は1年という決まった周期で繰り返す短い波。同じ『でこぼこ』でも、周期が決まっていて毎年同じ時期に繰り返すかどうかで呼び方が変わる。", "why_asked": "この後に出てくる移動平均や季節調整は、どちらもこのトレンドと季節変動という2つの動きを分けて取り出すための道具。まずこの2つの名前と違いを知らないと、何のためにそれらの道具を使うのかが分からなくなる。", "usecase": "小売店の月次売上、電力の使用量、観光地の来場者数など、『年々の伸び』と『季節ごとの繰り返し』の両方が混ざっているデータを分析するときに、この2つを分けて捉える。", "opt": ["正解。何年もかけた右肩上がりの大きな流れがトレンド、毎年同じ時期(夏)に繰り返す山がトレンドではなく季節変動。名前と中身が正しく対応している。", "トレンドと季節変動の名前が入れ替わっている。長期の右肩上がりの流れはトレンド、毎年同じ時期に繰り返す動きが季節変動というのが正しい対応。", "長期の流れと毎年繰り返す動きは性質がまったく違う別の動きであり、どちらもトレンドとまとめて呼ぶことはしない。区別する名前(季節変動)がちゃんと存在する。", "長期の流れと毎年繰り返す動きは性質がまったく違う別の動きであり、どちらも季節変動とまとめて呼ぶことはしない。区別する名前(トレンド)がちゃんと存在する。"]}'),

  ('stats16-q03', '時系列解析',
   '月・火・水の来客数がそれぞれ10人・14人・12人だった。この3日間の来客数を使って「3日移動平均(その日を含む直近3日間の平均)」を計算すると、水曜日の移動平均は何人になる？',
   NULL::text,
   '["12人", "36人", "14人", "13人"]',
   0, '[0]', 'single',
   '{"asked": "直近3日間の来客数から、3日移動平均を計算する手順。", "point": "移動平均は、直近数日分をそのつど合計して日数で割る。1日ずつ範囲をずらしながら計算し続ける。", "kid": "移動平均は、日々のでこぼこした数字を『直近何日か分をならして、1つの数字』にする方法。3日移動平均なら、その日を含む直近3日分を毎回足して3で割る。", "eg": "体重計に毎日乗ると、その日の食事や水分でポンと数字が上下してでこぼこする。でも直近3日分の平均を見るようにすると、日々のブレがならされて『本当はどっちに向かっているか』が見やすくなる。移動平均はこれと同じ発想。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">3日移動平均ででこぼこをならす</text>\n<line x1=\"30\" y1=\"118\" x2=\"315\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<rect x=\"45\" y=\"88\" width=\"20\" height=\"30\" fill=\"#2a2f3f\"/>\n<rect x=\"95\" y=\"72\" width=\"20\" height=\"46\" fill=\"#2a2f3f\"/>\n<rect x=\"145\" y=\"82\" width=\"20\" height=\"36\" fill=\"#2a2f3f\"/>\n<rect x=\"195\" y=\"58\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/>\n<rect x=\"245\" y=\"48\" width=\"20\" height=\"70\" fill=\"#2a2f3f\"/>\n<text x=\"55\" y=\"130\" fill=\"#8892a4\" font-size=\"9\">月10</text>\n<text x=\"105\" y=\"130\" fill=\"#8892a4\" font-size=\"9\">火14</text>\n<text x=\"155\" y=\"130\" fill=\"#8892a4\" font-size=\"9\">水12</text>\n<text x=\"205\" y=\"130\" fill=\"#8892a4\" font-size=\"9\">木16</text>\n<text x=\"255\" y=\"130\" fill=\"#8892a4\" font-size=\"9\">金18</text>\n<polyline points=\"55,94 105,86 155,88 205,74 255,70\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n<circle cx=\"155\" cy=\"88\" r=\"4\" fill=\"#c9a04a\"/>\n<text x=\"155\" y=\"70\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">水の移動平均12</text>\n<text x=\"170\" y=\"144\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">灰=日々の実数(でこぼこ)　黄線=3日移動平均(なめらか)</text>\n</svg>", "terms": [["移動平均", "直近数日分の値を、範囲をずらしながら平均し続けて、でこぼこをならす方法"], ["ウィンドウ(窓)", "移動平均を計算するときに使う、直近何日分かという範囲の幅。今回は3日"]], "think": "なぜ足すだけでなく3で割るのかがカギ。10・14・12をただ足した36は『3日ぶんの合計』であって、1日あたりの水準を表す数字ではない。1日あたりの『ならした値』を知りたいので、合計を日数(3)で割って、平均という1日分の物差しに戻す必要がある。この『足して、日数で割る』計算を、1日ずつ範囲をずらしながら繰り返すのが移動平均。", "calc": "来客数     月10  火14  水12\n3日分を足す  10+14+12 = 36\n3日で割る   36 ÷ 3 = 12  …これが水曜日の3日移動平均\n\n(木曜になったら、月を外して火・水・木の3日で計算し直す)", "vs": "移動平均は『直近数日分の値そのものをならす』計算であり、この後に出てくる『移動平均モデル(MAモデル)』とは名前が似ているだけの別物。MAモデルは値そのものではなく、過去の予測の誤差を使って次の値を予測する、まったく別の考え方。", "why_asked": "トレンドと季節変動が混ざったでこぼこのデータから、まずトレンドの形を見やすくするのが移動平均の役目。この後の自己相関や定常性の話は、多くの場合この『ならした後の動き』を念頭に置いて説明される。", "usecase": "株価チャートの『5日移動平均線』『25日移動平均線』、来客数や売上の日々の変動をならして傾向をつかみたいときなど、実務で最もよく使われる時系列の下ごしらえの方法。", "opt": ["正解。月・火・水の10・14・12を足すと36、3日で割ると12。これが水曜日時点の3日移動平均。", "36は10・14・12を足しただけの合計で、3で割る計算が抜けている。合計と平均は別の数字。", "14は水曜日ではなく火曜日1日だけの値。移動平均は複数日をならした値であり、1日分の実数をそのまま使うものではない。", "13は火・水の2日だけを使って(14+12)÷2としてしまった計算。3日移動平均なので、月・火・水の3日ぶんを使わなければならない。"]}'),

  ('stats16-q04', '時系列解析',
   '「今日の気温」と「1日前(昨日)の気温」を100日分ペアにして相関係数を計算したら、0.9という強い正の相関が出た。この「同じ時系列データを、時間をずらしてペアにしたときの相関」のことを何と呼ぶ？',
   NULL::text,
   '["自己相関(同じ時系列データを、時間をずらしてペアにして比べたときの相関)", "相互相関(別々の2つの時系列データ同士を比べたときの相関)", "偏自己相関(間に挟まる時点の影響を取り除いてから比べる、より詳しい相関)", "定常性(平均や分散が、時間が経っても変わらないという性質)"]',
   0, '[0]', 'single',
   '{"asked": "同じデータを時間差でペアにして比べたときの相関の名前。", "point": "同じ1つの時系列データを、時間をずらして自分自身とペアにした相関が自己相関。『自己』は相手が別のデータではなく自分自身であることを表す。", "kid": "いつもの相関係数は『身長と体重』のように別々の2つのものを比べる。自己相関は違って、『今日の気温』と『昨日の気温』のように、同じ1種類のデータを、時間をずらして自分自身と比べる。", "eg": "双子のきょうだいの今日の体調と昨日の体調を比べるようなもの。比べている相手は別人(別のデータ)ではなく、同じ人(同じデータ)の、時間がずれた姿。似ていればいるほど、自己相関は強くなる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">今日の気温と1日前の気温の散布図</text>\n<line x1=\"45\" y1=\"120\" x2=\"45\" y2=\"30\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"45\" y1=\"120\" x2=\"305\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<text x=\"20\" y=\"30\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">今日</text>\n<text x=\"290\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1日前</text>\n<line x1=\"50\" y1=\"115\" x2=\"300\" y2=\"35\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n<circle cx=\"70\" cy=\"100\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"95\" cy=\"95\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"85\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"140\" cy=\"80\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"165\" cy=\"70\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"190\" cy=\"68\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"210\" cy=\"60\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"235\" cy=\"55\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"255\" cy=\"48\" r=\"3\" fill=\"#60a5fa\"/><circle cx=\"280\" cy=\"42\" r=\"3\" fill=\"#60a5fa\"/>\n<text x=\"170\" y=\"140\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">点が右上がりの直線に近い ＝ 強い自己相関</text>\n</svg>", "terms": [["自己相関", "同じ時系列データを、時間をずらして自分自身とペアにしたときの相関"], ["ラグ(遅れ)", "何時点分ずらして比べるか、という時間差の大きさ。今回は1日ずらしたので『ラグ1』"]], "think": "なぜ『自己』とわざわざ付けて呼ぶのかがカギ。普段の相関係数は『身長』と『体重』のように、性質の違う2つの変数を比べる。しかし気温の自己相関は、比べる相手も『気温』であり、比べているデータの種類はまったく同じ。違うのは『いつの時点の値か』という時間だけ。この『相手が別の変数ではなく、自分自身の過去や未来である』という点を強調するために、自己(オート)という言葉を付けて自己相関と呼ぶ。", "vs": "相互相関は『気温』と『アイスの売上』のように別々の2種類のデータを時間差で比べる。自己相関は比べる相手が同じ1種類のデータである点が違う。", "why_asked": "この後に出てくる自己回帰モデル(ARモデル)は、過去の自分自身の値を使って次の値を予測する仕組み。過去の自分自身の値が今の値とどれくらい似ているか(自己相関の強さ)が分からないと、ARモデルがなぜ機能するのかが分からなくなる。", "usecase": "株価が『昨日の株価と今日の株価はどれくらい似ているか』を調べたり、気温や来客数の予測モデルを作る前に『何日前のデータが今日の予測に役立ちそうか』を調べたりするときに使う。", "opt": ["正解。今日の気温と1日前の気温は、比べている相手も『気温』という同じデータで、時間だけがずれている。この『自分自身との時間差の相関』が自己相関。", "相互相関は気温と別のデータ(例えばアイスの売上)のように、種類の違う2つのデータ同士を時間差で比べるときに使う言葉。今回は同じ気温同士を比べているので当てはまらない。", "偏自己相関は自己相関をさらに詳しくした指標で、間の時点の影響を除いてから比べる、より進んだ考え方。今回問われている基本の相関そのものではない。", "定常性は平均や分散が時間で変わらないという別の性質の名前で、2つの時点のデータがどれくらい似ているかを表す相関とは別物。"]}'),

  ('stats16-q05', '時系列解析',
   '時系列データの平均や分散(ばらつきの大きさ)が、時間が経っても変わらないという性質を何と呼ぶ？この後に学ぶARモデルなど、多くの時系列モデルはこの性質を前提として組み立てられている。',
   NULL::text,
   '["定常性", "季節性", "自己相関", "独立性"]',
   0, '[0]', 'single',
   '{"asked": "平均や分散が時間で変わらない、という性質の名前。", "point": "平均も分散もずっと同じ水準のまま上下しているのが定常。Bのように平均そのものが右肩上がりに動いていくのは非定常。", "kid": "定常性は、時系列データが『同じ場所を中心に、同じくらいの幅でずっと上下し続けている』という性質。平均の位置がどんどん動いていったり、上下の振れ幅がどんどん大きくなったりすると、定常ではなくなる。", "eg": "やじろべえに例えると分かりやすい。定常なデータは、いつも同じ位置を中心にゆらゆら揺れ続けるやじろべえ。非定常なデータは、揺れながらも中心の位置そのものがだんだん右にずれていってしまうやじろべえ。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">平均・ばらつきが一定／時間で変わる</text>\n<text x=\"85\" y=\"32\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">定常(A)</text>\n<rect x=\"25\" y=\"40\" width=\"120\" height=\"65\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<line x1=\"25\" y1=\"72\" x2=\"145\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n<polyline points=\"30,68 45,78 60,64 75,76 90,66 105,80 120,62 140,74\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.8\"/>\n<text x=\"85\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">平均も上下の幅もずっと同じ</text>\n<text x=\"255\" y=\"32\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">非定常(B)</text>\n<rect x=\"195\" y=\"40\" width=\"120\" height=\"65\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<polyline points=\"200,100 215,92 230,88 245,75 260,70 275,58 290,50 310,35\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.8\"/>\n<text x=\"255\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">平均がどんどん上がっていく</text>\n<text x=\"170\" y=\"140\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">Aのような性質を「定常性」と呼ぶ</text>\n</svg>", "terms": [["定常性", "時系列データの平均や分散が、時間が経っても変わらないという性質"], ["非定常", "平均や分散が時間とともに変わっていく、定常性を持たない状態。トレンドがある系列はたいてい非定常"]], "think": "なぜ多くの時系列モデルが定常性を前提にするのかがカギ。ARモデルのようなモデルは、過去のデータから学んだ『増え方・戻り方の癖』を使って、これからの値を予測する。もしデータの平均や分散が時間とともにどんどん変わってしまうなら、過去に学んだ癖が未来でも同じように成り立つとは限らず、予測の土台が崩れてしまう。平均や分散が変わらないという保証(定常性)があってはじめて、『過去に学んだ癖を、この先にも当てはめてよい』と言える。", "vs": "季節変動は『毎年同じ時期に繰り返す動き』というデータの中身の話。定常性は『平均や分散という統計的な性質が時間で変わらないか』という、また別の切り口の話。季節変動があっても、その繰り返し方自体が一定なら定常とみなせる場合もある。なお厳密には、平均・分散だけでなく『どれくらい離れた時点同士が似ているか』という関係も時間によって変わらない、という条件までそろって定常と呼ぶ。ここでは平均・分散の話に絞って捉えれば十分。", "why_asked": "この後のARモデル・MAモデル・ARMAモデルは、いずれも定常性を持つデータに対して組み立てられる。定常性という前提を知らずにこれらのモデルを使うと、トレンドが残ったままのデータに当てはめて、予測が大きく外れる原因になる。", "usecase": "時系列モデルを作る前に、対象のデータが定常かどうかを確認し、非定常ならトレンドを取り除く(差分をとる、など)処理をしてから予測モデルに入れる、という実務上の下ごしらえの判断基準として使う。", "opt": ["正解。平均や分散が時間によって変わらない性質を定常性と呼ぶ。Aのグラフのように、同じ水準・同じ幅で上下し続けている状態がこれにあたる。", "季節性(季節変動)は毎年同じ時期に繰り返す周期的な動きのことで、平均や分散そのものが変わらないかどうかを表す言葉ではない。", "自己相関はある時点と少し前の時点のデータがどれくらい似ているかを表す指標で、平均や分散が時間で変わらないという性質そのものを指す言葉ではない。", "独立性は一方の結果がもう一方に影響しないという別の性質で、時系列データの平均や分散が時間で変わらないかどうかとは異なる話。"]}'),

  ('stats16-q06', '時系列解析',
   'ある店の今日の売上を予測するのに、気温や広告費のような他の情報は使わず、昨日の売上・一昨日の売上といった「その店自身の過去の売上」だけを使って予測する、という考え方のモデルを何と呼ぶ？',
   NULL::text,
   '["自己回帰モデル(ARモデル)。過去の自分自身の値から、次の値を予測する", "移動平均モデル(MAモデル)。過去の予測がどれだけ外れたか(誤差)から、次の値を予測する", "ARMAモデル。ARモデルとMAモデルを組み合わせて、両方の考え方で予測する", "回帰分析。売上を、広告費や気温など他の変数から予測する"]',
   0, '[0]', 'single',
   '{"asked": "過去の自分自身の値だけを使って次の値を予測する、というモデルの名前。", "point": "使う材料が『その系列自身の過去の値』だけなら自己回帰モデル(ARモデル)。他の変数を使ったら、それはもう別の話(回帰分析)。", "kid": "ARモデルは、『今日の値を、昨日や一昨日という自分自身の過去の値だけから予測しよう』という考え方。天気や広告費のような、他の種類の情報はいっさい使わない。", "eg": "自分の去年の体重の変化だけを見て、来月の体重を予測するようなもの。食事の内容や運動量といった他の情報を一切使わず、『自分の過去の体重の動き方の癖』だけから、この先を予測するイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ARモデル：過去の自分自身の値だけを使う</text>\n<rect x=\"30\" y=\"40\" width=\"90\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<text x=\"75\" y=\"61\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">昨日の売上</text>\n<line x1=\"120\" y1=\"57\" x2=\"185\" y2=\"57\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/>\n<polygon points=\"185,57 177,52 177,62\" fill=\"#60a5fa\"/>\n<rect x=\"190\" y=\"40\" width=\"120\" height=\"34\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<text x=\"250\" y=\"61\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">今日の予測値</text>\n<text x=\"170\" y=\"100\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">✕ 気温・広告費など他の変数は使わない</text>\n<text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">「自己」＝自分自身の過去の値だけから予測する</text>\n</svg>", "terms": [["自己回帰モデル(ARモデル)", "過去の自分自身の値から、次の値を予測するモデル。ARはAuto Regressive(自分自身に対する回帰)の略"], ["回帰分析", "既に学んだ、ある変数を他の変数から予測する手法。ARモデルは『他の変数』の代わりに『自分自身の過去』を使う特別な形"]], "think": "なぜ『自己』回帰と呼ぶのかがカギ。普通の回帰分析は、予測したい変数(売上)を、それとは別の変数(広告費や気温)から予測する。ARモデルも『過去の値から今の値を予測する』という回帰の考え方そのものは同じだが、予測に使う材料が『別の変数』ではなく『同じ系列の過去の自分自身』である点が違う。この『相手が自分自身』という特徴を強調するために、自己(オート)という言葉を付けてAuto Regressive、自己回帰モデルと呼ぶ。", "calc": "AR(1)モデルの例(1つ前の値だけを使う場合)\n今日の予測 = 0.8 × 昨日の値\n昨日の売上が100万円のとき\n0.8 × 100 = 80  …今日の予測は80万円\n(0.8は「昨日の影響がどれくらい今日に残るか」を表す係数)", "vs": "回帰分析は他の変数(広告費・気温など)を使って予測する。ARモデルは他の変数をいっさい使わず、自分自身の過去の値だけを使う。『何を予測に使うか』がこの2つを見分ける決め手。", "why_asked": "この後に出てくるMAモデル・ARMAモデルは、いずれもARモデルの考え方を土台にしている。まず『過去の自分自身の値を使って予測する』という発想そのものを理解していないと、この先のモデルの違いが単なる名前の暗記になってしまう。", "usecase": "株価や気温、来客数のように、その値自身の過去の動き方に一定の癖(前の値に近い値が続きやすい、など)がありそうなデータの予測に使う。", "opt": ["正解。過去の自分自身の値(昨日・一昨日の売上)だけを使って今日の値を予測するのが自己回帰モデル(ARモデル)。", "移動平均モデル(MAモデル)は、過去の値そのものではなく、過去の予測がどれだけ外れていたか(誤差)を使って予測する、別の考え方のモデル。", "ARMAモデルはARモデルとMAモデルを組み合わせたモデルで、ARモデル単体よりも材料が多い、より進んだモデル。今回の『過去の値だけ』という条件に当てはまるのはARモデル単体の方。", "回帰分析は広告費や気温のような、売上とは別の変数を使って予測する手法。今回のように他の情報を使わず自分自身の過去だけを使う話には当てはまらない。"]}'),

  ('stats16-q07', '時系列解析',
   'ある予測モデルで、昨日は「80万円」と予測したが実際は「86万円」で、6万円ぶん予測が外れた(誤差が出た)。この「これまでの予測がどれだけ外れていたか(誤差)」を使って、次の値を予測する考え方のモデルを何と呼ぶ？',
   NULL::text,
   '["移動平均モデル(MAモデル)。過去の予測誤差から、次の値を予測する", "自己回帰モデル(ARモデル)。過去の自分自身の値から、次の値を予測する", "移動平均。直近数日分の値を平均して、でこぼこをならす方法", "ARMAモデル。ARモデルとMAモデルを組み合わせたモデル"]',
   0, '[0]', 'single',
   '{"asked": "過去の予測の誤差(ズレ)を使って次の値を予測する、というモデルの名前。", "point": "使う材料が『過去の予測がどれだけ外れていたか』ならMAモデル。『過去の値そのもの』ならARモデル。", "kid": "MAモデルは、『昨日の予測はこれだけ外れていた。じゃあ今日はその外れ具合を踏まえて、こう補正しよう』と考えるモデル。使うのは値そのものではなく、予測と実際のズレ(誤差)。", "eg": "ダーツで例えると分かりやすい。ARモデルは『前の一投がどこに刺さったか(値そのもの)』を見て次を狙う。MAモデルは『前の一投がどれだけ的から外れたか(ズレの大きさと方向)』を見て、次はその分を補正して狙うイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">MAモデル：過去の「予測のズレ」を使う</text>\n<text x=\"80\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">昨日の予測</text>\n<text x=\"80\" y=\"46\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">80万円</text>\n<text x=\"80\" y=\"66\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">昨日の実際</text>\n<text x=\"80\" y=\"78\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">86万円</text>\n<rect x=\"30\" y=\"86\" width=\"100\" height=\"26\" rx=\"4\" fill=\"#c47070\" opacity=\"0.5\"/>\n<text x=\"80\" y=\"103\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">誤差 +6万円</text>\n<line x1=\"135\" y1=\"99\" x2=\"195\" y2=\"99\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/>\n<polygon points=\"195,99 187,94 187,104\" fill=\"#60a5fa\"/>\n<rect x=\"200\" y=\"86\" width=\"120\" height=\"26\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<text x=\"260\" y=\"103\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">今日の予測を補正</text>\n<text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">値そのものではなく「外れ具合」を次に使う</text>\n</svg>", "terms": [["移動平均モデル(MAモデル)", "過去の予測誤差(ズレ)から、次の値を予測するモデル。MAはMoving Average(移動平均)の略"], ["予測誤差", "予測した値と、実際に起きた値との差。ズレの大きさと向き"]], "think": "なぜ『値そのもの』ではなく『誤差』を使うモデルが別に必要なのかがカギ。ARモデルは過去の値の水準そのものから次を予測するが、それだけでは説明しきれない、一時的な突発的な変動(急な出来事によるブレ)が残ることがある。MAモデルは、その『予測しきれなかった分(誤差)』が次にどう影響するかを直接モデル化することで、ARモデルだけでは拾いきれない動きを補う役目を持つ。", "vs": "名前がよく似ている『移動平均(でこぼこをならす方法)』とは別物。移動平均は直近数日分の値そのものを平均してならす計算。MAモデルは値ではなく過去の予測誤差を使って次を予測する、まったく別の考え方のモデル。名前の『移動平均』という部分だけを見て同じものだと思わないよう注意する。", "why_asked": "MAモデルは、この後のARMAモデルを理解するための片方の部品にあたる。ARモデルとの違い(値そのものを使うか、誤差を使うか)を先に区別しておかないと、ARMAモデルが『何と何を組み合わせたものか』が分からなくなる。", "usecase": "ARモデルだけでは説明しきれない、突発的な出来事(急な注文・急な欠品など)の影響が次の期間にも少し残るような予測の場面で、誤差の影響を織り込むために使われる。", "opt": ["正解。昨日の予測と実際の値との差(誤差)を使って、今日の予測を補正するのがMAモデル。値そのものではなく誤差を材料にする。", "ARモデルは過去の値そのもの(実際に何万円だったか)を使って予測するモデル。今回のように『誤差(ズレ)』を材料にする話には当てはまらない。", "移動平均は直近数日分の値を平均してでこぼこをならす、値そのものを扱う計算。名前は似ているが、過去の予測誤差を使って次を予測するMAモデルとは別物。", "ARMAモデルはARモデルとMAモデルの両方を組み合わせたモデルで、誤差だけでなく過去の値も同時に使う、より材料の多いモデル。今回の『誤差だけ』という話に当てはまるのはMAモデル単体の方。"]}'),

  ('stats16-q08', '時系列解析',
   '「過去の自分自身の値」を使って予測する部分と、「過去の予測誤差」を使って予測する部分を、両方合わせて1つの予測モデルにしたものを何と呼ぶ？',
   NULL::text,
   '["ARMAモデル。ARモデル(過去の値)とMAモデル(過去の誤差)を組み合わせたモデル", "自己回帰モデル(ARモデル)。過去の値だけを使い、過去の予測誤差は使わないモデル", "移動平均モデル(MAモデル)。過去の予測誤差だけを使い、過去の値そのものは使わないモデル", "移動平均。直近数日分の値を平均して、でこぼこをならすだけの単純な計算方法"]',
   0, '[0]', 'single',
   '{"asked": "ARモデルとMAモデルの両方を組み合わせたモデルの名前。", "point": "『過去の値』も『過去の誤差』も両方使って予測するのがARMAモデル。名前もAR+MAをそのままつなげたもの。", "kid": "ARMAモデルは、『昨日や一昨日の値そのもの(ARの部分)』と『これまでの予測がどれだけ外れていたか(MAの部分)』の両方を材料にして、今日の値を予測するモデル。名前のARMAも、ARとMAをそのままくっつけたもの。", "eg": "天気予報に例えると、『昨日・一昨日の気温の動き方(AR)』と『昨日の予報がどれだけ外れたか(MA)』の両方を踏まえて今日の予報を微調整するようなもの。片方だけより、両方を使ったほうが予測の材料が増える。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ARMA ＝ AR ＋ MA</text>\n<rect x=\"30\" y=\"34\" width=\"115\" height=\"40\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<text x=\"87\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">ARモデル</text>\n<text x=\"87\" y=\"65\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">過去の値</text>\n<text x=\"163\" y=\"60\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\">+</text>\n<rect x=\"180\" y=\"34\" width=\"130\" height=\"40\" rx=\"4\" fill=\"#c9a04a\" opacity=\"0.55\"/>\n<text x=\"245\" y=\"52\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">MAモデル</text>\n<text x=\"245\" y=\"65\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\">過去の予測誤差</text>\n<line x1=\"170\" y1=\"88\" x2=\"170\" y2=\"102\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<polygon points=\"170,106 165,98 175,98\" fill=\"#8892a4\"/>\n<rect x=\"70\" y=\"108\" width=\"200\" height=\"26\" rx=\"4\" fill=\"#6ab08d\" opacity=\"0.5\"/>\n<text x=\"170\" y=\"125\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">ARMAモデル(今日の予測)</text>\n</svg>", "terms": [["ARMAモデル", "自己回帰モデル(AR)と移動平均モデル(MA)を組み合わせた時系列モデル"], ["パラメータ", "ARの部分は何日前まで使うか、MAの部分は何日前の誤差まで使うか、というモデルの調整値"]], "think": "なぜ2つを組み合わせると予測がより良くなるのかがカギ。ARモデルは『過去の値の水準』からの続き方は捉えられるが、突発的な出来事による一時的なズレの残り方までは捉えにくい。MAモデルは逆に、そのズレの残り方は捉えられるが、値そのものの水準の続き方は捉えにくい。ARMAモデルは、AR部分で『値の続き方』を、MA部分で『ズレの残り方』を、それぞれ別々に受け持たせることで、片方だけでは拾いきれない動きを両方でカバーする。", "vs": "ARモデル単体、MAモデル単体は、それぞれ片方の材料しか使わない。ARMAモデルはその2つを両方使う、いわば『いいとこ取り』のモデル。どちらか片方の名前だけを答えると、半分の材料しか使っていないモデルを指してしまう。", "why_asked": "実務の時系列予測では、値の続き方(AR)だけでも、誤差の残り方(MA)だけでも説明しきれないデータが多い。ARMAモデルという『両方使う』選択肢を知っておかないと、片方だけのモデルで無理に説明しようとして、予測の精度が落ちる。", "usecase": "株価・気温・売上などの予測で、ARモデルだけ、MAモデルだけでは当てはまりが悪いときに、両方を組み合わせたARMAモデルを試す、という時系列予測の標準的な選択肢の1つとして使われる。", "opt": ["正解。過去の値(AR)と過去の予測誤差(MA)の両方を組み合わせて予測するのがARMAモデル。名前もARとMAをつなげたもの。", "自己回帰モデル(ARモデル)は過去の値だけを使うモデルで、過去の予測誤差は使わない。両方使う話には当てはまらない。", "移動平均モデル(MAモデル)は過去の予測誤差だけを使うモデルで、過去の値そのものは使わない。両方使う話には当てはまらない。", "移動平均は値そのものを平均してならす計算であり、モデルの名前ではない。過去の値と過去の誤差を組み合わせて予測する話とは別物。"]}'),

  ('stats16-q09', '時系列解析',
   'ある小売店の月次売上は、毎年12月だけ大きく跳ね上がる(季節変動)。この季節変動の影響を取り除き、「実質的にどれだけ売上の勢いが伸びているか(トレンド)」を見えやすくする処理を何と呼ぶ？',
   NULL::text,
   '["季節調整(データから季節変動の影響を取り除く処理)", "移動平均(直近数か月分の値を平均して、でこぼこをならす方法)", "自己相関(ある時点と少し前の時点のデータが、どれくらい似ているかを測る指標)", "定常性(平均や分散が時間によって変わらないという性質)"]',
   0, '[0]', 'single',
   '{"asked": "季節変動の影響を取り除いて、実質的な変化を見えやすくする処理の名前。", "point": "毎年決まって起きる季節変動ぶんを見積もって差し引くのが季節調整。残った部分が、季節の影響を除いた『実質的な動き』になる。", "kid": "季節調整は、『12月はだいたいいつもこれくらい跳ね上がる』という毎年おなじみの季節変動ぶんを見積もって、実際の売上からあらかじめ差し引いておく処理。そうすると、季節のおかげで伸びたのか、それとも本当にお店の実力として伸びたのかが見分けやすくなる。", "eg": "長袖と半袖どちらも着る人の体重を比べるときに、服の重さぶんを差し引いてから比べるようなもの。冬は厚着で重く測れてしまうが、その『厚着ぶん』を先に引いておけば、本当の体重の変化が見えやすくなる。季節調整もこれと同じで、『季節のかさ増しぶん』を先に引いておく。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">季節調整：12月の山を取り除く</text>\n<text x=\"90\" y=\"30\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">調整前(実際の月次売上)</text>\n<line x1=\"30\" y1=\"80\" x2=\"290\" y2=\"80\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<polyline points=\"30,72 55,68 80,66 105,62 130,110 155,60 180,58 205,54 230,108 255,50 280,46\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/>\n<text x=\"130\" y=\"122\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">12月</text>\n<text x=\"230\" y=\"120\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">12月</text>\n<line x1=\"30\" y1=\"132\" x2=\"290\" y2=\"132\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n<text x=\"90\" y=\"146\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">↓ 季節変動(12月の山)を取り除く</text>\n</svg>", "terms": [["季節調整", "時系列データから季節変動の影響を取り除き、実質的な変化を見えやすくする処理"], ["季節指数", "各月ごとに『平均よりどれくらい多い・少ないか』を表す、季節変動の大きさの目安"]], "think": "なぜ季節変動を取り除かないと実質的な伸びが分からないのかがカギ。12月の売上が前年の12月より増えていたとしても、それが『お店の実力が伸びた』のか、それとも『たまたま今年は12月の季節変動そのものが大きかった』のかは、実際の数字を見ただけでは区別がつかない。あらかじめ『12月はいつもこれくらい増える』という季節変動ぶんを見積もって差し引いておけば、残った部分は季節の影響を受けない、純粋な実力の変化(トレンドに近い動き)として比べられるようになる。", "vs": "移動平均も似た場面で使われるが、目的が違う。移動平均は日々・月々のでこぼこ全般を単純にならす計算。季節調整は『毎年同じ時期に決まって起きる季節変動』という特定の要因だけを狙って見積もり、取り除く処理。何を取り除こうとしているかが違う。", "why_asked": "ニュースの経済統計で『季節調整済み』という言葉がよく使われる。この処理を知らないと、単に『先月より増えた・減った』という数字だけを見て、それが季節のせいなのか実質的な変化なのかを取り違えてしまう。", "usecase": "小売の月次売上、雇用統計、GDPなど、季節ごとの決まった動きが混ざっている経済データを、年単位・月単位で公平に比較したいときに使われる。", "opt": ["正解。毎年決まって起きる季節変動の影響を見積もって差し引き、実質的な変化を見えやすくするのが季節調整。", "移動平均は直近数日・数か月分の値を平均してでこぼこ全般をならす計算で、季節変動という特定の要因だけを狙って取り除く処理ではない。", "自己相関はある時点と少し前の時点のデータの似ている度合いを測る指標で、季節変動を取り除く処理そのものではない。", "定常性は平均や分散が時間で変わらないという性質の名前で、季節変動の影響を取り除く処理を指す言葉ではない。"]}'),

  ('stats16-q10', '時系列解析',
   '株価・気温・毎月の売上のように、「時間とともに値が変化していくもの」を分析し、トレンド・季節変動・自己相関などを手がかりに傾向をつかんだり将来を予測したりする、一連の手法をまとめて何と呼ぶ？',
   NULL::text,
   '["時系列解析(時間とともに変化するデータを分析し、傾向をつかんだり将来を予測したりする手法群)", "回帰分析(ある変数を、それとは別の変数から予測する、時間の順番を特に前提にしない一般的な手法)", "因果推論(相関関係の裏にある、原因と結果の関係を明らかにしようとする、また別の手法)", "ベイズ統計(新しい証拠が得られるたびに、確率の見込みを更新していく考え方に立つ統計学)"]',
   0, '[0]', 'single',
   '{"asked": "時間とともに変化するデータを扱う手法群を、まとめて何と呼ぶか。", "point": "対象が『時間の順番に意味があるデータ』であり、そこにトレンド・季節変動・自己相関・定常性といった、時間だからこそ出てくる考え方を使う分析全般が時系列解析。", "kid": "ここまで見てきたトレンド、季節変動、移動平均、自己相関、定常性、ARモデル・MAモデル・ARMAモデル、季節調整は、全部『時間とともに変化するデータをどう分析するか』という、同じ1つのテーマの中の道具だった。この一連の分析全体をまとめて時系列解析と呼ぶ。", "eg": "健康診断に例えると分かりやすい。血圧・体重・体温という別々の検査項目も、『体の状態を診る』という1つの目的でまとめて健康診断と呼ぶ。同じように、トレンドを見る・周期を見る・過去との似方を見るという別々の作業も、『時間とともに変化するものを分析する』という1つの目的でまとめて時系列解析と呼ぶ。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">時間とともに変化するものすべてが対象</text>\n<circle cx=\"75\" cy=\"55\" r=\"26\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"75\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">株価</text>\n<text x=\"75\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">日々の値動き</text>\n<circle cx=\"170\" cy=\"55\" r=\"26\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"170\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">気温</text>\n<text x=\"170\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">季節の移り変わり</text>\n<circle cx=\"265\" cy=\"55\" r=\"26\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"265\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">売上</text>\n<text x=\"265\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">月ごとの推移</text>\n<line x1=\"101\" y1=\"55\" x2=\"144\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"196\" y1=\"55\" x2=\"239\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<rect x=\"55\" y=\"102\" width=\"230\" height=\"30\" rx=\"5\" fill=\"#6ab08d\" opacity=\"0.5\"/>\n<text x=\"170\" y=\"121\" fill=\"#141720\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">時系列解析でまとめて扱う</text>\n</svg>", "terms": [["時系列解析", "時間とともに変化するデータを分析し、傾向の把握や将来の予測を行う一連の手法"], ["予測", "過去から今までの動き方をもとに、まだ起きていない先の値を見積もること。時系列解析の主な目的の1つ"]], "think": "なぜこれらをひとまとめの名前で呼ぶ必要があるのかがカギ。トレンド・季節変動・自己相関・定常性・ARモデルなどは、それぞれ別の道具に見えるが、どれも共通して『データの並び順(時間)そのものに意味がある』という、最初に学んだ性質を前提にしている。この共通の前提を持つ分析をまとめて呼ぶ名前があることで、『このデータは時間の順番が大事だから、普段の相関や回帰とは別の見方(時系列解析)で扱おう』という判断がしやすくなる。", "vs": "回帰分析は『他の変数から予測する』手法全般を指す、より広い言葉。時系列解析はその中でも特に『時間の順番に意味があるデータ』を対象にし、トレンドや季節変動、自己相関といった時間特有の考え方を使う点が異なる。", "why_asked": "ここまで学んできたトレンド・季節変動・移動平均・自己相関・定常性・ARモデル・MAモデル・ARMAモデル・季節調整のすべてが、この時系列解析という1つの大きな枠組みの中の部品だったと分かることで、バラバラに覚えた用語がつながって整理される。", "usecase": "株価の値動き予測、気温や天気の予測、来月の売上予測、電力需要の予測など、『これまでの推移から、この先どうなりそうか』を考えるあらゆる場面で使われる。", "opt": ["正解。時間とともに変化するデータを対象に、トレンド・季節変動・自己相関などの考え方を使って傾向をつかみ、将来を予測する一連の手法が時系列解析。", "回帰分析は、ある変数をそれとは別の変数から予測する、より一般的な手法。時間の順番そのものに意味があるかどうかを前提にはしていない、時系列解析より広い言葉。", "因果推論は相関関係の裏にある原因と結果の関係を明らかにする手法で、時間の順番に沿ったデータの分析そのものを指す言葉ではない。", "ベイズ統計は新しい証拠が得られるたびに確率の見込みを更新していく考え方で、時間とともに変化するデータの分析全般を指す言葉ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
